u_z1z2 return_svpwm_5active_optz1z2(svpwm_5active_2zero_24sector_SV_sequence_t version, float theta, float kappa, float M, int sector_24){

	const float theta_min = 0.0f;
	const float theta_max = 2*UZ_PIf/24;
	const float M_min = 0.0f;
	const float M_max = 1.15f;

	// kappa_idx
    float kappa_ar[] = {1.0f, 1.5f, 2.0f, 10.0f};
    int kappa_idx = find_nearest_index(kappa_ar, 4, kappa);

	// check version
    uz_assert(version >= 0 && version < 16);

    float u_z1 = 0;
    float u_z2 = 0;


	// sector
	uz_assert(sector_24 > 0 && sector_24 <= 24);

	// repeats for 3 times per full rotation
	int sector_8 = ((sector_24 - 1) % 8) + 1;

	// angle over one sector
	float theta_pi_12 = fmodf(theta, (float)M_PI / 12.0f);

	if (sector_8 == 1){

		u_z1 = uz_interp2_uniform(M_min, M_max, 47, theta_min, theta_max, 65, svpwm_5active_optz1z2_LUT[kappa_idx][version][1], M, theta_pi_12);
		u_z2 = uz_interp2_uniform(M_min, M_max, 47, theta_min, theta_max, 65, svpwm_5active_optz1z2_LUT[kappa_idx][version][2], M, theta_pi_12);
		u_z1 = u_z1 * M;
		u_z2 = u_z2 * M;
	}
	else if (sector_8 == 2){
		theta_pi_12 = UZ_PIf/12 - theta_pi_12;
		u_z1 = uz_interp2_uniform(M_min, M_max, 47, theta_min, theta_max, 65, svpwm_5active_optz1z2_LUT[kappa_idx][version][1], M, theta_pi_12);
		u_z2 = uz_interp2_uniform(M_min, M_max, 47, theta_min, theta_max, 65, svpwm_5active_optz1z2_LUT[kappa_idx][version][2], M, theta_pi_12);
	    u_z1 = u_z1 - 0.5f;
	    u_z2 = u_z2 - 0.5f;
	}
	else if (sector_8 == 3){
		u_z1 = uz_interp2_uniform(M_min, M_max, 47, theta_min, theta_max, 65, svpwm_5active_optz1z2_LUT[kappa_idx][version][1], M, theta_pi_12);
		u_z2 = uz_interp2_uniform(M_min, M_max, 47, theta_min, theta_max, 65, svpwm_5active_optz1z2_LUT[kappa_idx][version][2], M, theta_pi_12);
		u_z1 = -(u_z1) - 0.5f;
		u_z2 = u_z2 - 0.5f;
	}
	else if (sector_8 == 4){
		theta_pi_12 = UZ_PIf/12 - theta_pi_12;
		u_z1 = uz_interp2_uniform(M_min, M_max, 47, theta_min, theta_max, 65, svpwm_5active_optz1z2_LUT[kappa_idx][version][1], M, theta_pi_12);
		u_z2 = uz_interp2_uniform(M_min, M_max, 47, theta_min, theta_max, 65, svpwm_5active_optz1z2_LUT[kappa_idx][version][2], M, theta_pi_12);
	    u_z1 = -(u_z1) - 0.5f;
	    u_z2 = u_z2 - 0.5f;
	}
	else if (sector_8 == 5){
		u_z1 = uz_interp2_uniform(M_min, M_max, 47, theta_min, theta_max, 65, svpwm_5active_optz1z2_LUT[kappa_idx][version][1], M, theta_pi_12);
		u_z2 = uz_interp2_uniform(M_min, M_max, 47, theta_min, theta_max, 65, svpwm_5active_optz1z2_LUT[kappa_idx][version][2], M, theta_pi_12);
		u_z1 = -(u_z1) - 0.5f;
		u_z2 = -(u_z2) - 0.5f;
	}
	else if (sector_8 == 6){
		theta_pi_12 = UZ_PIf/12 - theta_pi_12;
		u_z1 = uz_interp2_uniform(M_min, M_max, 47, theta_min, theta_max, 65, svpwm_5active_optz1z2_LUT[kappa_idx][version][1], M, theta_pi_12);
		u_z2 = uz_interp2_uniform(M_min, M_max, 47, theta_min, theta_max, 65, svpwm_5active_optz1z2_LUT[kappa_idx][version][2], M, theta_pi_12);
	    u_z1 = -(u_z1) - 0.5f;
	    u_z2 = -(u_z2) - 0.5f;
	}
	else if (sector_8 == 7){
		u_z1 = uz_interp2_uniform(M_min, M_max, 47, theta_min, theta_max, 65, svpwm_5active_optz1z2_LUT[kappa_idx][version][1], M, theta_pi_12);
		u_z2 = uz_interp2_uniform(M_min, M_max, 47, theta_min, theta_max, 65, svpwm_5active_optz1z2_LUT[kappa_idx][version][2], M, theta_pi_12);
		u_z1 = u_z1  - 0.5f;
		u_z2 = -(u_z2) - 0.5f;
	}
	else {//if (sector_8 == 8)
		theta_pi_12 = UZ_PIf/12 - theta_pi_12;
		u_z1 = uz_interp2_uniform(M_min, M_max, 47, theta_min, theta_max, 65, svpwm_5active_optz1z2_LUT[kappa_idx][version][1], M, theta_pi_12);
		u_z2 = uz_interp2_uniform(M_min, M_max, 47, theta_min, theta_max, 65, svpwm_5active_optz1z2_LUT[kappa_idx][version][2], M, theta_pi_12);
		u_z1 = u_z1 - 0.5f;
		u_z2 = -(u_z2) - 0.5f;
	}

	return (u_z1z2) {u_z1, u_z2};;
}



